// Tag a handful of parent parts with an assembly type so the list-view column has data to show.
const ASSEMBLY_OVERRIDES: Record<string, 'Assembled' | 'Disassembled'> = {
  'PART-001': 'Assembled',
  'PART-002': 'Assembled',
  'PART-003': 'Assembled',
  'PART-004': 'Assembled',
  'PART-005': 'Assembled',
  'PART-008': 'Disassembled',
  'PART-009': 'Disassembled',
  'PART-011': 'Disassembled',
  'PART-013': 'Assembled',
  'PART-017': 'Disassembled',
  'PART-020': 'Assembled',
  'PART-021': 'Disassembled',
  'COMP-026': 'Disassembled',
}
for (const p of mockParts) {
  if (ASSEMBLY_OVERRIDES[p.id] && !p.assemblyType) {
    p.assemblyType = ASSEMBLY_OVERRIDES[p.id]
  }
}

// Every part should carry a condition — default parents to 'New' so the list/detail views
// always have a value. Variant-type parts keep whatever condition they were created with.
for (const p of mockParts) {
  if (!p.condition) {
    p.condition = 'New'
  }
}

// Sprinkle a handful of Refurbished-condition sample parents so the column shows variety.
const REFURB_PARENTS = new Set(['PART-006', 'PART-014', 'PART-019'])
for (const p of mockParts) {
  if (REFURB_PARENTS.has(p.id)) {
    p.condition = 'Refurbished'
  }
}
